% 1. Force the original vectors into clean row vectors
% X_orig = X_org(:)';
% Y_orig = Y_org(:)';

% 2. Pinpoint the rising zero-crossing
idx_all = find(Y_orig(1:end-1) <= 0 & Y_orig(2:end) > 0);
idx = idx_all(1);
x0 = X_orig(idx);     x1 = X_orig(idx+1);
y0 = Y_orig(idx);     y1 = Y_orig(idx+1);
x_zero = x0 - y0 * (x1 - x0) / (y1 - y0); 

% 3. Periodic Phase Shift & Wrap Around
X_shifted = X_orig - x_zero;
X_wrapped = mod(X_shifted, 360);

% Sort the wrapped vectors chronologically
[X_wrapped, sortIdx] = sort(X_wrapped);
Y_wrapped = Y_orig(sortIdx);

% --- FORCING EXCLUSIVELY PERFECT 0V BOUNDARIES ---
% Instead of blending neighboring points, we force the cycle to 
% start and end exactly at 0.0 Volts.
X_wrapped = [0, X_wrapped, 360];
Y_wrapped = [0, Y_wrapped, 0];  
% -------------------------------------------------

% 4. Sample onto your final full-revolution electrical grid
theta_elec = 0 : 1.2 : 360;  % Extends from 0 to 360 Electrical Degrees (301 points)
BEMF_shape = interp1(X_wrapped, Y_wrapped, theta_elec, 'spline');

% Direct assertion check to ensure it works perfectly
% BEMF_shape1(1) = 0;
% BEMF_shape1(end) = 0;
% 5. Convert Electrical Degrees to Mechanical Degrees (0 to 120)
pole_pairs = 3; 
theta_mech = theta_elec / pole_pairs; % Maps 0:1.2:360 electrical to 0:0.4:120 mechanical

% 6. Plot the results to verify
figure;
plot(X_orig, Y_orig, 'r--', 'DisplayName', 'Original Waveform'); hold on;
plot(theta_elec, BEMF_shape, 'b--', 'LineWidth', 1.5, 'DisplayName', 'Phase-Shifted to 0V (Rising)');
plot(theta_mech, BEMF_shape, 'g-.', 'LineWidth', 2, 'DisplayName', 'Shifted Back-EMF in mechanical degree');
xlim([-10 370]);
grid on;
xlabel('Mechanical Angle (0-120)-Electrical Angle (0-360)');
ylabel('Back-EMF (V)');
title('BDnEV1(X8701)backEMF 2000rpm Phase-A Back-EMF profile');
legend('Location', 'best');